#!/usr/bin/env python3
"""Generate embedded C pack/unpack code from a DBC file.

usage: dbcgen.py can/zonecore.dbc include/zc/zc_can_db.h src/com/zc_can_db.c [--check]

--check exits non-zero if the committed generated files are stale (used in CI).
"""
from __future__ import annotations

import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import dbc  # noqa: E402

HDR = "/* AUTO-GENERATED by tools/dbcgen.py from {src} -- DO NOT EDIT */\n"


def ctype(s: dbc.Signal) -> str:
    if s.is_integer:
        return "uint8_t" if s.length <= 8 else "uint16_t"
    return "float"


def fmt(x: float) -> str:
    r = repr(float(x))
    return r + "f" if ("e" in r or "." in r) else r + ".0f"


def gen_header(msgs: dict[str, dbc.Message], src: str) -> str:
    out = [HDR.format(src=src), "#ifndef ZC_CAN_DB_H\n#define ZC_CAN_DB_H\n",
           "#include <stdint.h>\n"]
    for m in msgs.values():
        u = m.name.upper()
        out.append(f"#define ZC_CAN_ID_{u} 0x{m.frame_id:03X}U")
        out.append(f"#define ZC_CAN_DLC_{u} {m.dlc}U\n")
        out.append("typedef struct {")
        for s in m.signals:
            unit = f" /**< [{s.unit}] */" if s.unit else ""
            out.append(f"    {ctype(s)} {s.name};{unit}")
        out.append(f"}} zc_can_{m.name.lower()}_t;\n")
        out.append(f"void zc_can_pack_{m.name.lower()}(const zc_can_{m.name.lower()}_t *msg, uint8_t data[{m.dlc}]);")
        out.append(f"void zc_can_unpack_{m.name.lower()}(const uint8_t data[{m.dlc}], zc_can_{m.name.lower()}_t *msg);\n")
    out.append("#endif /* ZC_CAN_DB_H */\n")
    return "\n".join(out)


def gen_source(msgs: dict[str, dbc.Message], src: str) -> str:
    out = [HDR.format(src=src), '#include "zc/zc_can_db.h"\n',
           "static uint64_t load_le(const uint8_t *d, uint8_t n)\n{\n"
           "    uint64_t w = 0U;\n"
           "    for (uint8_t i = 0U; i < n; i++) { w |= ((uint64_t)d[i]) << (8U * i); }\n"
           "    return w;\n}\n",
           "static void store_le(uint64_t w, uint8_t *d, uint8_t n)\n{\n"
           "    for (uint8_t i = 0U; i < n; i++) { d[i] = (uint8_t)(w >> (8U * i)); }\n}\n",
           "static int32_t phys_to_raw(float phys, float factor, float offset, int32_t lo, int32_t hi)\n{\n"
           "    const float r = (phys - offset) / factor;\n"
           "    int32_t raw = (int32_t)((r >= 0.0f) ? (r + 0.5f) : (r - 0.5f));\n"
           "    if (raw < lo) { raw = lo; }\n    if (raw > hi) { raw = hi; }\n    return raw;\n}\n",
           "static int32_t sext(uint64_t raw, uint8_t len)\n{\n"
           "    const uint64_t sign = 1ULL << (len - 1U);\n"
           "    return (int32_t)((raw ^ sign) - sign);\n}\n"]
    for m in msgs.values():
        n = m.name.lower()
        out.append(f"void zc_can_pack_{n}(const zc_can_{n}_t *msg, uint8_t data[{m.dlc}])\n{{")
        out.append("    uint64_t w = 0U;")
        for s in m.signals:
            mask = f"0x{(1 << s.length) - 1:X}ULL"
            lo, hi = s.raw_limits()
            if s.is_integer:
                out.append(f"    w |= ((uint64_t)msg->{s.name} & {mask}) << {s.start}U;")
            else:
                out.append(
                    f"    w |= ((uint64_t)(uint32_t)phys_to_raw(msg->{s.name}, {fmt(s.factor)}, {fmt(s.offset)}, "
                    f"{lo}, {hi}) & {mask}) << {s.start}U;")
        out.append(f"    store_le(w, data, {m.dlc}U);\n}}\n")
        out.append(f"void zc_can_unpack_{n}(const uint8_t data[{m.dlc}], zc_can_{n}_t *msg)\n{{")
        out.append(f"    const uint64_t w = load_le(data, {m.dlc}U);")
        for s in m.signals:
            mask = f"0x{(1 << s.length) - 1:X}ULL"
            raw = f"((w >> {s.start}U) & {mask})"
            if s.is_integer:
                out.append(f"    msg->{s.name} = ({ctype(s)}){raw};")
            elif s.signed:
                out.append(f"    msg->{s.name} = ((float)sext({raw}, {s.length}U) * {fmt(s.factor)}) + {fmt(s.offset)};")
            else:
                out.append(f"    msg->{s.name} = ((float){raw} * {fmt(s.factor)}) + {fmt(s.offset)};")
        out.append("}\n")
    return "\n".join(out)


def main(argv: list[str]) -> int:
    src, hdr_p, c_p = argv[1:4]
    check = "--check" in argv
    msgs = dbc.parse(src)
    rel = Path(src).as_posix()
    files = {Path(hdr_p): gen_header(msgs, rel), Path(c_p): gen_source(msgs, rel)}
    stale = False
    for p, text in files.items():
        if check:
            if not p.exists() or p.read_text() != text:
                print(f"STALE: {p}")
                stale = True
        else:
            p.write_text(text)
            print(f"wrote {p}")
    return 1 if stale else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
